.header:has(.nav-toggle:checked) .burger .burger-close { display: block; }
.mobile-nav { display: none; position: absolute; left: 0; right: 0; top: 100%; background: #fff; border-bottom: 1px solid var(--border); padding-bottom: 20px; box-shadow: 0 24px 40px -24px rgba(11, 37, 69, .35); }
.header:has(.nav-toggle:checked) .mobile-nav { display: block; }
.m-link { display: flex; align-items: center; justify-content: space-between; min-height: 52px; font-size: 17px; font-weight: 600; border-bottom: 1px solid var(--border); }
.m-link-ic { display: inline-flex; align-items: center; gap: 10px; }
.m-sub { display: flex; flex-wrap: wrap; gap: 8px; padding: 12px 0; border-bottom: 1px solid var(--border); }
.m-actions { display: grid; gap: 10px; margin-top: 20px; }
.m-contact { display: flex; align-items: center; gap: 8px; margin-top: 16px; font-size: 14px; color: var(--muted); }

.toast-slot { position: absolute; right: var(--gutter); top: calc(100% + 10px); z-index: 70; width: min(420px, calc(100% - 2 * var(--gutter))); }
.toast { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: start; gap: 4px 12px; padding: 16px; background: #fff; border: 1.5px solid var(--navy); border-radius: var(--r-lg); box-shadow: 0 18px 40px -22px rgba(11, 37, 69, .45); }
.toast-ic { color: var(--navy); padding-top: 2px; }
.toast-body { display: flex; flex-direction: column; font-size: 14px; line-height: 1.4; }
.toast-body span { color: var(--muted); }
.toast-close { width: 32px; height: 32px; margin: -6px -6px 0 0; }
.toast-btn { grid-column: 2 / 4; justify-self: start; margin-top: 8px; }

.header-checkout .header-bar { height: 72px; }
.secure-note { display: inline-flex; align-items: center; gap: 8px; margin-left: auto; font-size: 14px; font-weight: 600; color: var(--navy); }
.back-link { display: inline-flex; align-items: center; gap: 6px; font-size: 14px; font-weight: 600; padding: 8px 12px; border-radius: var(--r-md); border: 1.5px solid var(--sky-light); }
.back-link:hover { border-color: var(--navy); }

/* ---------- Footer ---------- */
.footer { background: var(--navy); color: rgba(255, 255, 255, .84); padding: 72px 0 32px; font-size: 15px; margin-top: auto; }
.footer-top { display: grid; grid-template-columns: 1.5fr repeat(3, minmax(0, 1fr)); gap: 40px; padding-bottom: 48px; border-bottom: 1px solid rgba(255, 255, 255, .14); }
.footer-logo { display: inline-block; font-size: 22px; font-weight: 800; color: #fff; margin-bottom: 16px; }
.footer-logo span { color: var(--sky); }
.footer-brand p { max-width: 360px; line-height: 1.6; }
.footer-contact { display: grid; gap: 8px; margin-top: 20px; }
.footer-contact li { display: flex; align-items: center; gap: 10px; }
.footer-contact .ic { color: var(--sky-light); }
.footer-title { font-size: 15px; font-weight: 700; color: #fff; margin-bottom: 16px; }
.footer-links { display: grid; gap: 10px; }
.footer-links a { color: rgba(255, 255, 255, .84); }
.footer-links a:hover { color: #fff; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--sky); }
.site .footer :focus-visible { outline-color: #fff; }
.footer-mid { display: grid; grid-template-columns: auto 1fr auto; align-items: end; gap: 40px; padding: 36px 0; border-bottom: 1px solid rgba(255, 255, 255, .14); }
.pay-list { display: flex; flex-wrap: wrap; gap: 8px; }
.pay-list li { display: inline-flex; align-items: center; height: 30px; padding: 0 10px; border-radius: var(--r-sm); background: #fff; color: var(--navy); font-size: 12px; font-weight: 700; }
.pay-list-light li { background: var(--page); border: 1px solid var(--border); }
.footer-trust { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px 28px; }
.footer-trust li { display: inline-flex; align-items: center; gap: 8px; font-size: 14px; }
.footer-trust .ic { color: var(--sky-light); }
.social { display: flex; gap: 8px; }
.social-link { display: grid; place-items: center; width: 40px; height: 40px; border-radius: var(--r-md); border: 1px solid rgba(255, 255, 255, .28); color: #fff; }
.social-link:hover { border-color: var(--sky-light); background: rgba(255, 255, 255, .06); }
.footer-bottom { display: flex; justify-content: space-between; gap: 24px; padding-top: 24px; font-size: 13px; color: rgba(255, 255, 255, .72); }
.footer-bottom p:last-child { max-width: 560px; text-align: right; }
.footer-min { border-top: 1px solid var(--border); background: var(--page); font-size: 13px; color: var(--muted); }
.footer-min-bar { display: flex; justify-content: space-between; align-items: center; gap: 16px; min-height: 64px; flex-wrap: wrap; padding-block: 12px; }
.footer-min ul { display: flex; gap: 20px; flex-wrap: wrap; }
.footer-min a { text-decoration: underline; text-underline-offset: 3px; }

/* ---------- Product visuals (book / device) ---------- */
.visual { position: relative; width: 100%; aspect-ratio: 5 / 4; display: grid; place-items: center; container-type: inline-size; }
.book { position: relative; width: 50cqw; aspect-ratio: 3 / 4; display: flex; flex-direction: column; padding: 4.6cqw 4cqw 4cqw 6cqw; border-radius: 2px 6px 6px 2px; background: var(--navy); color: #fff; container-type: inline-size; box-shadow: 0 18px 26px -18px rgba(11, 37, 69, .6); overflow: hidden; }
.book::before { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 5%; background: rgba(0, 0, 0, .22); }
.book::after { content: ""; position: absolute; right: -30%; top: -12%; width: 80%; aspect-ratio: 1; border-radius: 50%; border: 6cqw solid rgba(255, 255, 255, .06); }
.book > span { position: relative; z-index: 1; }
.book-brand { font-size: 6.4cqw; font-weight: 700; line-height: 1; }
.book-brand b { color: var(--sky-light); }
.book-kicker { margin-top: 13cqw; font-size: 7cqw; font-weight: 600; color: var(--sky-light); line-height: 1; }
.book-title { margin-top: 2cqw; font-size: 19cqw; font-weight: 800; line-height: 1; letter-spacing: 0; }
.book-sub { margin-top: 3cqw; font-size: 6.4cqw; font-weight: 500; opacity: .85; line-height: 1; }
.book-art { margin-top: auto; align-self: flex-end; width: 46cqw; color: var(--sky-light); }
.book-art svg { width: 100%; height: auto; stroke-width: 1.25; }
.book-band { align-self: flex-start; margin-top: 3cqw; padding: 2cqw 3.4cqw; border-radius: 2px; background: var(--yellow); color: var(--navy); font-size: 5.4cqw; font-weight: 700; line-height: 1.1; white-space: nowrap; }
.book-motor { background: #1d4a78; }
.book-motor .book-art { color: #fff; }
.book-brom { background: var(--sky); color: var(--navy); }
.book-brom .book-brand b, .book-brom .book-kicker { color: #fff; }
.book-brom .book-art { color: var(--navy); }
.book-brom::after { border-color: rgba(255, 255, 255, .16); }
.book-light { background: #fff; color: var(--navy); box-shadow: 0 0 0 1px var(--border), 0 18px 26px -18px rgba(11, 37, 69, .45); }
.book-light::before { background: var(--navy); width: 6%; }
.book-light::after { border-color: var(--panel); }
.book-light .book-brand b { color: var(--sky); }
.book-light .book-kicker { color: #3a7cb0; }
.book-light .book-art { color: var(--sky); }

.device { position: relative; width: 34cqw; aspect-ratio: 3 / 4.6; display: flex; flex-direction: column; align-items: center; gap: 5cqw; padding: 7cqw 6cqw; background: #fff; border: 1.4cqw solid var(--navy); border-radius: 5cqw; container-type: inline-size; box-shadow: 0 18px 26px -18px rgba(11, 37, 69, .6); }
.device-top { display: flex; gap: 4cqw; align-self: stretch; }
.device-top i { height: 5cqw; flex: 1; border-radius: 3cqw; background: var(--panel); }
.device-top i:first-child { background: var(--navy); flex: .6; }
.device-ring { --p: 50; position: relative; display: grid; place-items: center; align-content: center; width: 66cqw; aspect-ratio: 1; border-radius: 50%; background: conic-gradient(var(--sky) calc(var(--p) * 1%), var(--panel) 0); }
.device-ring::before { content: ""; position: absolute; inset: 9cqw; border-radius: 50%; background: #fff; }

